import { MINE_DEFS } from './index';

/** `src/oldsmoke/mines/ANCHORS.md` must equal this (see anchorsDoc.test.ts). A13, A8 and A9 build against these ids. */
export function minesAnchorsDoc(): string {
  const out = [
    '# Deepgate mines: anchors, triggers and blockers',
    '',
    'Generated by `npx vite-node tools/gen-region-docs.ts`; do not edit. Local metres from each mine\'s lift landing (yaw 0 faces -Z).',
    'These anchors are defined by the interiors plugin when the mine builds, so they are not in `src/oldsmoke/ANCHORS.md`.',
    '',
  ];
  for (const d of MINE_DEFS) {
    out.push(`## ${d.id}`, '', `Door \`${d.doors[0].doorId}\`: arrives at \`${d.doors[0].inside}\`, leaves by \`${d.doors[0].exit}\` to \`${d.doors[0].outside}\`.`, '');
    out.push('| id | local x | local z |', '| --- | --- | --- |');
    for (const a of d.anchors) out.push(`| ${a.id} | ${a.x} | ${a.z} |`);
    if (d.triggers.length) {
      out.push('', 'Triggers (box centre, half size):', '');
      for (const t of d.triggers) out.push(`- \`${t.id}\` at (${t.center.x}, ${t.center.y}, ${t.center.z}), half (${t.half.x}, ${t.half.y}, ${t.half.z})`);
    }
    if (d.blockers.length) {
      out.push('', 'Blockers (open by default):', '');
      for (const b of d.blockers) out.push(`- \`${b.id}\` x ${b.rect.x0}..${b.rect.x1}, z ${b.rect.z0}..${b.rect.z1}`);
    }
    out.push('');
  }
  return out.join('\n');
}
